-- OTOTR Finance migration promoted from a reviewed candidate.
-- Source: candidate-contract-version-replace-rpc.sql
-- Source SHA256: AC4C99C0269C9AEC2B78DB35D740DFFD349CF0D74F5F8F06CAB039CF5147E61A
-- Local replay required before any staging promotion.
-- OTOTR CONTRACT VERSION REPLACE RPC CANDIDATE
create or replace function finance_private.current_contract_version_replace_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_contract_version_replace_scope(p_actor_id uuid,p_contract_version_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_api.authorize_contract_version_replace(p_contract_version_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when auth.uid() is null or p_permission<>'finance.contract-versions.update' then null::jsonb else finance_private.resolve_contract_version_replace_scope(auth.uid(),p_contract_version_id,p_permission) end$$;
create or replace function finance_api.commit_contract_version_replace(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_contract_version_id uuid,p_effective_from date,p_effective_to date,p_currency_code text,p_document_ids uuid[],p_content_hash text,p_note_hash text,p_expected_version bigint,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare v record;v_existing record;v_docs integer;v_new bigint;v_purpose text;v_payload jsonb;v_previous text;v_audit text;
begin
 if not finance_private.current_contract_version_replace_committer_is_trusted() then raise exception using errcode='42501',message='trusted contract version replace committer required';end if;
 if p_effective_from is null or (p_effective_to is not null and p_effective_to<=p_effective_from) or p_currency_code!~'^[A-Z]{3}$' or p_document_ids is null or pg_catalog.cardinality(p_document_ids)<1 or p_content_hash!~'^[a-fA-F0-9]{64}$' or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') or p_expected_version<1 or pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='invalid contract version replace command';end if;
 select cv.*,fc.legal_entity_id,fc.dealer_legal_entity_id,fc.status contract_status into v from finance.contract_versions cv join finance.franchise_contracts fc on fc.id=cv.contract_id where cv.id=p_contract_version_id for update of cv,fc;if not found then raise exception using errcode='P0002',message='contract version not found';end if;
 select om.payload into v_existing from finance.outbox_messages om where om.legal_entity_id=v.legal_entity_id and om.event_type='CONTRACT_VERSION_DRAFT_REPLACED' and om.aggregate_id=v.id and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if v_existing.payload->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','versionId',v.id,'contractId',v.contract_id,'versionNo',v.version_no,'status','DRAFT','validFrom',v_existing.payload->>'validFrom','validTo',v_existing.payload->>'validTo','currencyCode',v_existing.payload->>'currencyCode','version',(v_existing.payload->>'version')::bigint);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if v.legal_entity_id<>p_legal_entity_id or v.dealer_legal_entity_id<>p_dealer_legal_entity_id or v.contract_status in ('TERMINATED','DISCARDED') or v.status<>'DRAFT' or v.version<>p_expected_version then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=p_dealer_account_id and da.legal_entity_id=p_legal_entity_id and da.dealer_legal_entity_id=p_dealer_legal_entity_id and b.id=p_branch_id) then raise exception using errcode='42501',message='contract version replace three dimensional scope denied';end if;
 if (select pg_catalog.count(*) from pg_catalog.unnest(p_document_ids) x)<>(select pg_catalog.count(distinct x) from pg_catalog.unnest(p_document_ids) x) then raise exception using errcode='23514',message='contract version documents must be unique';end if;
 select pg_catalog.count(distinct dr.external_document_id) into v_docs from finance.document_references dr where dr.legal_entity_id=p_legal_entity_id and dr.status='ACTIVE' and dr.external_document_id=any(p_document_ids);if v_docs<>pg_catalog.cardinality(p_document_ids) then raise exception using errcode='23514',message='all contract version documents must be active';end if;
 v_new:=v.version+1;v_purpose:='CONTRACT_VERSION_EVIDENCE_V'||v_new::text;update finance.contract_versions set currency_code=p_currency_code,effective_from=p_effective_from,effective_to=p_effective_to,content_hash=p_content_hash,evidence_object_key='DOCUMENT_LINKS:'||p_content_hash,version=v_new,correlation_id=p_correlation_id where id=v.id;
 insert into finance.document_links(legal_entity_id,document_reference_id,subject_type,subject_id,purpose_code,created_by,correlation_id) select p_legal_entity_id,dr.id,'CONTRACT_VERSION',v.id,v_purpose,p_actor_id,p_correlation_id from finance.document_references dr where dr.legal_entity_id=p_legal_entity_id and dr.status='ACTIVE' and dr.external_document_id=any(p_document_ids);
 v_payload:=pg_catalog.jsonb_build_object('versionId',v.id,'contractId',v.contract_id,'dealerLegalEntityId',v.dealer_legal_entity_id,'branchId',p_branch_id,'versionNo',v.version_no,'validFrom',p_effective_from,'validTo',p_effective_to,'currencyCode',p_currency_code,'contentHash',p_content_hash,'evidencePurpose',v_purpose,'noteHash',p_note_hash,'documentCount',v_docs,'version',v_new,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.contract','CONTRACT_VERSION_DRAFT_REPLACED','CONTRACT_VERSION',v.id,v_new,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=p_legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||v.id::text||':CONTRACT_VERSION_DRAFT_REPLACED:'||p_content_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,before_hash,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','CONTRACT_VERSION_DRAFT_REPLACED','CONTRACT_VERSION',v.id,'ALLOW',v.content_hash,p_content_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('contractId',v.contract_id,'branchId',p_branch_id,'versionNo',v.version_no,'evidencePurpose',v_purpose,'noteHash',p_note_hash,'documentCount',v_docs,'previousVersion',v.version),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','UPDATED','versionId',v.id,'contractId',v.contract_id,'versionNo',v.version_no,'status','DRAFT','validFrom',p_effective_from,'validTo',p_effective_to,'currencyCode',p_currency_code,'version',v_new);
end$$;
revoke all on function finance_private.current_contract_version_replace_committer_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_contract_version_replace_scope(uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_api.authorize_contract_version_replace(uuid,text) from public,anon;grant execute on function finance_api.authorize_contract_version_replace(uuid,text) to authenticated;revoke all on function finance_api.commit_contract_version_replace(uuid,uuid,uuid,uuid,uuid,uuid,date,date,text,uuid[],text,text,bigint,text,text,uuid) from public,anon,authenticated;
